from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def replace_once(path: Path, old: str, new: str):
    text = path.read_text(encoding="utf-8")
    if new in text:
        return
    if old not in text:
        raise SystemExit(
            f"\nNão encontrei o bloco esperado em:\n{path}\n\n"
            "Isto evita alterar o ficheiro errado. Envia-me o conteúdo desse ficheiro se acontecer."
        )
    path.write_text(text.replace(old, new, 1), encoding="utf-8")

FILES = {'apps/mobile/lib/repositories/financial_documents_repository.dart': "import 'dart:typed_data';\n\nimport 'package:file_picker/file_picker.dart';\nimport 'package:supabase_flutter/supabase_flutter.dart';\n\nimport '../core/app_config.dart';\nimport '../core/app_session.dart';\nimport '../core/permissions.dart';\n\nclass FinancialDocumentsRepository {\n  static const String bucketName = 'financial-documents';\n  static const int maxFileBytes = 20 * 1024 * 1024;\n\n  SupabaseClient get _client => Supabase.instance.client;\n  String get _clubId => AppSession.instance.clubId;\n\n  bool get canView =>\n      AppSession.instance.can(AppPermission.viewTreasury) ||\n      AppSession.instance.can(AppPermission.approveExpenseRequests);\n\n  bool get canManage =>\n      AppSession.instance.can(AppPermission.createTreasuryMovement) ||\n      AppSession.instance.can(AppPermission.approveExpenseRequests);\n\n  Future<List<Map<String, dynamic>>> listForTransaction(\n    String transactionId,\n  ) async {\n    _requireView();\n    if (AppConfig.demoMode) return const <Map<String, dynamic>>[];\n\n    final response = await _client\n        .from('financial_transaction_documents')\n        .select(\n          'id,club_id,transaction_id,source_attachment_id,document_type,'\n          'origin,storage_path,original_file_name,mime_type,file_size,'\n          'is_primary,created_at,created_by,updated_at,updated_by',\n        )\n        .eq('club_id', _clubId)\n        .eq('transaction_id', transactionId)\n        .order('is_primary', ascending: false)\n        .order('created_at')\n        .order('id');\n\n    return List<Map<String, dynamic>>.from(response);\n  }\n\n  Future<List<Map<String, dynamic>>> uploadFiles({\n    required String transactionId,\n    required String documentType,\n    required List<PlatformFile> files,\n  }) async {\n    _requireManage();\n    if (AppConfig.demoMode) {\n      throw StateError('O carregamento de documentos não está disponível em Demo.');\n    }\n    if (!documentTypes.contains(documentType)) {\n      throw ArgumentError('Categoria de documento inválida.');\n    }\n    if (files.isEmpty) return const <Map<String, dynamic>>[];\n\n    final uploaded = <Map<String, dynamic>>[];\n    for (final file in files) {\n      final Uint8List? bytes = file.bytes;\n      if (bytes == null || bytes.isEmpty) {\n        throw StateError(\n          'Não foi possível ler ${file.name}. Seleciona novamente o ficheiro.',\n        );\n      }\n      if (bytes.length > maxFileBytes) {\n        throw StateError('${file.name} ultrapassa o limite de 20 MB.');\n      }\n\n      final safeName = _safeFileName(file.name);\n      final timestamp = DateTime.now().microsecondsSinceEpoch;\n      final path = '$_clubId/transactions/$transactionId/'\n          '${timestamp}_$safeName';\n      final mimeType = mimeTypeForExtension(file.extension);\n\n      await _client.storage.from(bucketName).uploadBinary(\n            path,\n            bytes,\n            fileOptions: FileOptions(\n              contentType: mimeType,\n              upsert: false,\n            ),\n          );\n\n      try {\n        final id = await _client.rpc(\n          'add_financial_transaction_document_v1',\n          params: {\n            'target_club': _clubId,\n            'p_transaction': transactionId,\n            'p_document_type': documentType,\n            'p_storage_path': path,\n            'p_original_file_name': file.name,\n            'p_mime_type': mimeType,\n            'p_file_size': bytes.length,\n          },\n        );\n        uploaded.add({\n          'id': id.toString(),\n          'transaction_id': transactionId,\n          'document_type': documentType,\n          'origin': 'direct',\n          'storage_path': path,\n          'original_file_name': file.name,\n          'mime_type': mimeType,\n          'file_size': bytes.length,\n        });\n      } catch (_) {\n        await _client.storage.from(bucketName).remove([path]);\n        rethrow;\n      }\n    }\n    return uploaded;\n  }\n\n  Future<String> signedUrl(Map<String, dynamic> document) async {\n    _requireView();\n    final path = document['storage_path']?.toString();\n    if (path == null || path.isEmpty) {\n      throw StateError('Documento sem ficheiro associado.');\n    }\n    if (AppConfig.demoMode) {\n      throw StateError('A abertura de ficheiros não está disponível em Demo.');\n    }\n    return _client.storage.from(bucketName).createSignedUrl(path, 300);\n  }\n\n  Future<void> setPrimary({\n    required String transactionId,\n    required String documentId,\n  }) async {\n    _requireManage();\n    if (AppConfig.demoMode) return;\n\n    await _client.rpc(\n      'set_primary_financial_transaction_document_v1',\n      params: {\n        'target_club': _clubId,\n        'p_transaction': transactionId,\n        'p_document': documentId,\n      },\n    );\n  }\n\n  Future<void> deleteDocument({\n    required String transactionId,\n    required Map<String, dynamic> document,\n  }) async {\n    _requireManage();\n    if (!isDeletable(document)) {\n      throw StateError(\n        'Este documento pertence ao processo financeiro original e não pode ser eliminado aqui.',\n      );\n    }\n    if (AppConfig.demoMode) return;\n\n    final response = await _client.rpc(\n      'delete_financial_transaction_document_v1',\n      params: {\n        'target_club': _clubId,\n        'p_transaction': transactionId,\n        'p_document': document['id'].toString(),\n      },\n    );\n    final path = response?.toString();\n    if (path != null && path.isNotEmpty && path != 'null') {\n      try {\n        await _client.storage.from(bucketName).remove([path]);\n      } catch (_) {\n        // O registo já foi removido com sucesso. Um objeto órfão privado no\n        // Storage pode ser limpo posteriormente sem comprometer a contabilidade.\n      }\n    }\n  }\n\n  static const Set<String> documentTypes = {\n    'receipt',\n    'payment_proof',\n    'invoice_other',\n  };\n\n  static String documentTypeLabel(String? value) => switch (value) {\n        'receipt' => 'Talão / recibo',\n        'payment_proof' => 'Comprovativo de pagamento',\n        'invoice_other' => 'Fatura / PDF / outro',\n        _ => 'Documento',\n      };\n\n  static bool isImage(Map<String, dynamic> document) {\n    final mime = document['mime_type']?.toString().toLowerCase() ?? '';\n    if (mime.startsWith('image/')) return true;\n    final name = document['original_file_name']?.toString().toLowerCase() ?? '';\n    return name.endsWith('.jpg') ||\n        name.endsWith('.jpeg') ||\n        name.endsWith('.png') ||\n        name.endsWith('.webp');\n  }\n\n  static bool isPdf(Map<String, dynamic> document) {\n    final mime = document['mime_type']?.toString().toLowerCase() ?? '';\n    if (mime == 'application/pdf') return true;\n    final name = document['original_file_name']?.toString().toLowerCase() ?? '';\n    return name.endsWith('.pdf');\n  }\n\n  static bool isDeletable(Map<String, dynamic> document) =>\n      document['source_attachment_id'] == null &&\n      document['origin']?.toString() != 'request';\n\n  static String? mimeTypeForExtension(String? extension) {\n    switch (extension?.toLowerCase()) {\n      case 'jpg':\n      case 'jpeg':\n        return 'image/jpeg';\n      case 'png':\n        return 'image/png';\n      case 'webp':\n        return 'image/webp';\n      case 'pdf':\n        return 'application/pdf';\n      default:\n        return null;\n    }\n  }\n\n  String _safeFileName(String value) {\n    final normalized = value\n        .trim()\n        .replaceAll(RegExp(r'[^A-Za-z0-9._-]+'), '_')\n        .replaceAll(RegExp(r'_+'), '_');\n    return normalized.isEmpty ? 'documento' : normalized;\n  }\n\n  void _requireView() {\n    if (!canView) {\n      throw StateError('Sem permissão para ver documentos financeiros.');\n    }\n  }\n\n  void _requireManage() {\n    if (!canManage) {\n      throw StateError('Sem permissão para gerir documentos financeiros.');\n    }\n  }\n}\n", 'apps/mobile/lib/widgets/financial_document_gallery.dart': "import 'package:file_picker/file_picker.dart';\nimport 'package:flutter/material.dart';\nimport 'package:url_launcher/url_launcher.dart';\n\nimport '../repositories/financial_documents_repository.dart';\n\nclass FinancialDocumentGallery extends StatefulWidget {\n  const FinancialDocumentGallery({\n    super.key,\n    required this.repository,\n    required this.transactionId,\n    required this.canManage,\n    this.onChanged,\n  });\n\n  final FinancialDocumentsRepository repository;\n  final String transactionId;\n  final bool canManage;\n  final Future<void> Function()? onChanged;\n\n  @override\n  State<FinancialDocumentGallery> createState() =>\n      _FinancialDocumentGalleryState();\n}\n\nclass _FinancialDocumentGalleryState extends State<FinancialDocumentGallery> {\n  late Future<List<Map<String, dynamic>>> _future;\n  bool _busy = false;\n\n  @override\n  void initState() {\n    super.initState();\n    _reload();\n  }\n\n  void _reload() {\n    _future = widget.repository.listForTransaction(widget.transactionId);\n  }\n\n  Future<void> _refresh() async {\n    setState(_reload);\n    await _future;\n  }\n\n  Future<void> _notifyChanged() async {\n    final callback = widget.onChanged;\n    if (callback != null) await callback();\n    await _refresh();\n  }\n\n  Future<void> _addDocuments() async {\n    if (_busy) return;\n    final type = await showModalBottomSheet<String>(\n      context: context,\n      showDragHandle: true,\n      builder: (context) => SafeArea(\n        child: Wrap(\n          children: [\n            const ListTile(\n              title: Text(\n                'Categoria do documento',\n                style: TextStyle(fontWeight: FontWeight.w800),\n              ),\n            ),\n            ListTile(\n              leading: const Icon(Icons.receipt_long_outlined),\n              title: const Text('Talão / recibo'),\n              onTap: () => Navigator.pop(context, 'receipt'),\n            ),\n            ListTile(\n              leading: const Icon(Icons.payments_outlined),\n              title: const Text('Comprovativo de pagamento'),\n              onTap: () => Navigator.pop(context, 'payment_proof'),\n            ),\n            ListTile(\n              leading: const Icon(Icons.picture_as_pdf_outlined),\n              title: const Text('Fatura / PDF / outro'),\n              onTap: () => Navigator.pop(context, 'invoice_other'),\n            ),\n          ],\n        ),\n      ),\n    );\n    if (type == null || !mounted) return;\n\n    final result = await FilePicker.platform.pickFiles(\n      allowMultiple: true,\n      withData: true,\n      type: FileType.custom,\n      allowedExtensions: const ['pdf', 'jpg', 'jpeg', 'png', 'webp'],\n    );\n    if (result == null || result.files.isEmpty || !mounted) return;\n\n    setState(() => _busy = true);\n    try {\n      await widget.repository.uploadFiles(\n        transactionId: widget.transactionId,\n        documentType: type,\n        files: result.files,\n      );\n      await _notifyChanged();\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(\n          content: Text(\n            result.files.length == 1\n                ? 'Documento adicionado.'\n                : '${result.files.length} documentos adicionados.',\n          ),\n        ),\n      );\n    } catch (error) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(content: Text('Não foi possível carregar: $error')),\n      );\n    } finally {\n      if (mounted) setState(() => _busy = false);\n    }\n  }\n\n  Future<void> _open(Map<String, dynamic> document) async {\n    try {\n      final url = await widget.repository.signedUrl(document);\n      if (!mounted) return;\n\n      if (FinancialDocumentsRepository.isImage(document)) {\n        await showDialog<void>(\n          context: context,\n          builder: (context) => Dialog(\n            insetPadding: const EdgeInsets.all(16),\n            child: Stack(\n              children: [\n                ConstrainedBox(\n                  constraints:\n                      const BoxConstraints(maxWidth: 1100, maxHeight: 820),\n                  child: InteractiveViewer(\n                    minScale: 0.8,\n                    maxScale: 5,\n                    child: Image.network(url, fit: BoxFit.contain),\n                  ),\n                ),\n                Positioned(\n                  top: 8,\n                  right: 8,\n                  child: IconButton.filledTonal(\n                    onPressed: () => Navigator.pop(context),\n                    icon: const Icon(Icons.close),\n                  ),\n                ),\n              ],\n            ),\n          ),\n        );\n        return;\n      }\n\n      final launched = await launchUrl(\n        Uri.parse(url),\n        mode: LaunchMode.externalApplication,\n      );\n      if (!launched) {\n        throw StateError('Não foi possível abrir o documento.');\n      }\n    } catch (error) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(content: Text('$error')),\n      );\n    }\n  }\n\n  Future<void> _setPrimary(Map<String, dynamic> document) async {\n    if (_busy) return;\n    setState(() => _busy = true);\n    try {\n      await widget.repository.setPrimary(\n        transactionId: widget.transactionId,\n        documentId: document['id'].toString(),\n      );\n      await _notifyChanged();\n    } catch (error) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(content: Text('$error')),\n      );\n    } finally {\n      if (mounted) setState(() => _busy = false);\n    }\n  }\n\n  Future<void> _delete(Map<String, dynamic> document) async {\n    if (_busy) return;\n    final confirmed = await showDialog<bool>(\n      context: context,\n      builder: (context) => AlertDialog(\n        title: const Text('Eliminar documento?'),\n        content: Text(\n          'Eliminar “${document['original_file_name'] ?? 'Documento'}” deste movimento?',\n        ),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.pop(context, false),\n            child: const Text('Cancelar'),\n          ),\n          FilledButton.tonal(\n            onPressed: () => Navigator.pop(context, true),\n            child: const Text('Eliminar'),\n          ),\n        ],\n      ),\n    );\n    if (confirmed != true || !mounted) return;\n\n    setState(() => _busy = true);\n    try {\n      await widget.repository.deleteDocument(\n        transactionId: widget.transactionId,\n        document: document,\n      );\n      await _notifyChanged();\n    } catch (error) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(content: Text('$error')),\n      );\n    } finally {\n      if (mounted) setState(() => _busy = false);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return FutureBuilder<List<Map<String, dynamic>>>(\n      future: _future,\n      builder: (context, snapshot) {\n        if (snapshot.hasError) {\n          return Card(\n            child: ListTile(\n              leading: const Icon(Icons.error_outline),\n              title: const Text('Erro ao carregar documentos'),\n              subtitle: Text('${snapshot.error}'),\n            ),\n          );\n        }\n        if (!snapshot.hasData) {\n          return const Card(\n            child: SizedBox(\n              height: 180,\n              child: Center(child: CircularProgressIndicator()),\n            ),\n          );\n        }\n\n        final documents = snapshot.data!;\n        Map<String, dynamic>? primary;\n        for (final document in documents) {\n          if (document['is_primary'] == true) {\n            primary = document;\n            break;\n          }\n        }\n        primary ??= documents.isEmpty ? null : documents.first;\n\n        return Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            Row(\n              children: [\n                Expanded(\n                  child: Text(\n                    'Documentos & comprovativos',\n                    style: Theme.of(context).textTheme.titleLarge?.copyWith(\n                          fontWeight: FontWeight.w900,\n                        ),\n                  ),\n                ),\n                if (widget.canManage)\n                  FilledButton.tonalIcon(\n                    onPressed: _busy ? null : _addDocuments,\n                    icon: _busy\n                        ? const SizedBox.square(\n                            dimension: 17,\n                            child: CircularProgressIndicator(strokeWidth: 2),\n                          )\n                        : const Icon(Icons.add_photo_alternate_outlined),\n                    label: const Text('Adicionar'),\n                  ),\n              ],\n            ),\n            const SizedBox(height: 10),\n            if (primary == null)\n              Card(\n                child: InkWell(\n                  onTap: widget.canManage ? _addDocuments : null,\n                  child: const SizedBox(\n                    height: 170,\n                    child: Center(\n                      child: Column(\n                        mainAxisSize: MainAxisSize.min,\n                        children: [\n                          Icon(Icons.folder_open_outlined, size: 44),\n                          SizedBox(height: 8),\n                          Text('Sem documentos associados.'),\n                          SizedBox(height: 4),\n                          Text('PDF ou imagens · máximo 20 MB por ficheiro'),\n                        ],\n                      ),\n                    ),\n                  ),\n                ),\n              )\n            else ...[\n              _PrimaryDocumentCard(\n                repository: widget.repository,\n                document: primary,\n                onOpen: () => _open(primary!),\n              ),\n              const SizedBox(height: 10),\n              SizedBox(\n                height: 118,\n                child: ListView.separated(\n                  scrollDirection: Axis.horizontal,\n                  itemCount: documents.length,\n                  separatorBuilder: (_, __) => const SizedBox(width: 8),\n                  itemBuilder: (context, index) {\n                    final document = documents[index];\n                    return _DocumentThumbnail(\n                      repository: widget.repository,\n                      document: document,\n                      canManage: widget.canManage,\n                      onOpen: () => _open(document),\n                      onPrimary: document['is_primary'] == true\n                          ? null\n                          : () => _setPrimary(document),\n                      onDelete: widget.canManage &&\n                              FinancialDocumentsRepository.isDeletable(document)\n                          ? () => _delete(document)\n                          : null,\n                    );\n                  },\n                ),\n              ),\n              const SizedBox(height: 8),\n              const Text(\n                'Os documentos herdados de pedidos/reembolsos ficam protegidos contra eliminação nesta galeria.',\n              ),\n            ],\n          ],\n        );\n      },\n    );\n  }\n}\n\nclass _PrimaryDocumentCard extends StatelessWidget {\n  const _PrimaryDocumentCard({\n    required this.repository,\n    required this.document,\n    required this.onOpen,\n  });\n\n  final FinancialDocumentsRepository repository;\n  final Map<String, dynamic> document;\n  final VoidCallback onOpen;\n\n  @override\n  Widget build(BuildContext context) {\n    final isImage = FinancialDocumentsRepository.isImage(document);\n    final label = FinancialDocumentsRepository.documentTypeLabel(\n      document['document_type']?.toString(),\n    );\n\n    return AspectRatio(\n      aspectRatio: 16 / 7,\n      child: Card(\n        clipBehavior: Clip.antiAlias,\n        child: InkWell(\n          onTap: onOpen,\n          child: Stack(\n            fit: StackFit.expand,\n            children: [\n              if (isImage)\n                FutureBuilder<String>(\n                  future: repository.signedUrl(document),\n                  builder: (context, snapshot) {\n                    if (!snapshot.hasData) {\n                      return const Center(child: CircularProgressIndicator());\n                    }\n                    return Image.network(snapshot.data!, fit: BoxFit.cover);\n                  },\n                )\n              else\n                Container(\n                  alignment: Alignment.center,\n                  child: Column(\n                    mainAxisSize: MainAxisSize.min,\n                    children: [\n                      Icon(\n                        FinancialDocumentsRepository.isPdf(document)\n                            ? Icons.picture_as_pdf_outlined\n                            : Icons.description_outlined,\n                        size: 64,\n                      ),\n                      const SizedBox(height: 8),\n                      Padding(\n                        padding: const EdgeInsets.symmetric(horizontal: 24),\n                        child: Text(\n                          document['original_file_name']?.toString() ??\n                              'Documento',\n                          textAlign: TextAlign.center,\n                          maxLines: 2,\n                          overflow: TextOverflow.ellipsis,\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n              Positioned(\n                left: 10,\n                top: 10,\n                child: Chip(\n                  avatar: const Icon(Icons.star, size: 17),\n                  label: Text('Principal · $label'),\n                  visualDensity: VisualDensity.compact,\n                ),\n              ),\n              Positioned(\n                right: 10,\n                bottom: 10,\n                child: FilledButton.tonalIcon(\n                  onPressed: onOpen,\n                  icon: const Icon(Icons.open_in_new),\n                  label: const Text('Abrir'),\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass _DocumentThumbnail extends StatelessWidget {\n  const _DocumentThumbnail({\n    required this.repository,\n    required this.document,\n    required this.canManage,\n    required this.onOpen,\n    this.onPrimary,\n    this.onDelete,\n  });\n\n  final FinancialDocumentsRepository repository;\n  final Map<String, dynamic> document;\n  final bool canManage;\n  final VoidCallback onOpen;\n  final VoidCallback? onPrimary;\n  final VoidCallback? onDelete;\n\n  @override\n  Widget build(BuildContext context) {\n    final primary = document['is_primary'] == true;\n    final image = FinancialDocumentsRepository.isImage(document);\n\n    return SizedBox(\n      width: 112,\n      child: Card(\n        clipBehavior: Clip.antiAlias,\n        child: Stack(\n          fit: StackFit.expand,\n          children: [\n            InkWell(\n              onTap: onOpen,\n              child: image\n                  ? FutureBuilder<String>(\n                      future: repository.signedUrl(document),\n                      builder: (context, snapshot) {\n                        if (!snapshot.hasData) {\n                          return const Center(\n                            child: CircularProgressIndicator(strokeWidth: 2),\n                          );\n                        }\n                        return Image.network(snapshot.data!, fit: BoxFit.cover);\n                      },\n                    )\n                  : Column(\n                      mainAxisAlignment: MainAxisAlignment.center,\n                      children: [\n                        Icon(\n                          FinancialDocumentsRepository.isPdf(document)\n                              ? Icons.picture_as_pdf_outlined\n                              : Icons.description_outlined,\n                          size: 34,\n                        ),\n                        const SizedBox(height: 4),\n                        Padding(\n                          padding: const EdgeInsets.symmetric(horizontal: 5),\n                          child: Text(\n                            FinancialDocumentsRepository.documentTypeLabel(\n                              document['document_type']?.toString(),\n                            ),\n                            textAlign: TextAlign.center,\n                            maxLines: 2,\n                            overflow: TextOverflow.ellipsis,\n                            style: Theme.of(context).textTheme.labelSmall,\n                          ),\n                        ),\n                      ],\n                    ),\n            ),\n            if (primary)\n              const Positioned(\n                left: 4,\n                bottom: 4,\n                child: Icon(Icons.star, size: 20),\n              ),\n            if (document['origin'] == 'request')\n              const Positioned(\n                left: 4,\n                top: 4,\n                child: Tooltip(\n                  message: 'Herdado do pedido financeiro',\n                  child: Icon(Icons.link, size: 20),\n                ),\n              ),\n            if (canManage && (onPrimary != null || onDelete != null))\n              Positioned(\n                right: 0,\n                top: 0,\n                child: PopupMenuButton<String>(\n                  iconSize: 20,\n                  padding: EdgeInsets.zero,\n                  onSelected: (value) {\n                    if (value == 'primary') onPrimary?.call();\n                    if (value == 'delete') onDelete?.call();\n                  },\n                  itemBuilder: (_) => [\n                    if (onPrimary != null)\n                      const PopupMenuItem(\n                        value: 'primary',\n                        child: Text('Definir como principal'),\n                      ),\n                    if (onDelete != null)\n                      const PopupMenuItem(\n                        value: 'delete',\n                        child: Text('Eliminar documento'),\n                      ),\n                  ],\n                ),\n              ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n", 'apps/mobile/lib/screens/financial_transaction_documents_screen.dart': "import 'package:flutter/material.dart';\n\nimport '../repositories/financial_documents_repository.dart';\nimport '../widgets/financial_document_gallery.dart';\n\nclass FinancialTransactionDocumentsScreen extends StatelessWidget {\n  const FinancialTransactionDocumentsScreen({\n    super.key,\n    required this.transaction,\n    this.onChanged,\n  });\n\n  final Map<String, dynamic> transaction;\n  final Future<void> Function()? onChanged;\n\n  @override\n  Widget build(BuildContext context) {\n    final repository = FinancialDocumentsRepository();\n    final transactionId = transaction['id']?.toString() ?? '';\n    final kind = transaction['kind']?.toString();\n    final isIncome = kind == 'income';\n    final isTransfer = kind == 'transfer';\n\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('Documentos do movimento'),\n      ),\n      body: ListView(\n        padding: const EdgeInsets.fromLTRB(16, 16, 16, 48),\n        children: [\n          Card(\n            child: Padding(\n              padding: const EdgeInsets.all(16),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: [\n                  Row(\n                    children: [\n                      CircleAvatar(\n                        child: Icon(\n                          isTransfer\n                              ? Icons.swap_horiz\n                              : isIncome\n                                  ? Icons.arrow_downward\n                                  : Icons.arrow_upward,\n                        ),\n                      ),\n                      const SizedBox(width: 12),\n                      Expanded(\n                        child: Column(\n                          crossAxisAlignment: CrossAxisAlignment.start,\n                          children: [\n                            Text(\n                              transaction['description']?.toString() ??\n                                  'Movimento',\n                              style: Theme.of(context)\n                                  .textTheme\n                                  .titleLarge\n                                  ?.copyWith(fontWeight: FontWeight.w900),\n                            ),\n                            const SizedBox(height: 3),\n                            Text(\n                              [\n                                transaction['transaction_date']?.toString(),\n                                transaction['account_name']?.toString(),\n                                transaction['cost_center_name']?.toString(),\n                              ]\n                                  .where((value) =>\n                                      value != null && value.trim().isNotEmpty)\n                                  .join(' • '),\n                            ),\n                          ],\n                        ),\n                      ),\n                      Text(\n                        '${isIncome ? '+' : isTransfer ? '' : '-'}${_money(transaction['amount'])}',\n                        style: Theme.of(context)\n                            .textTheme\n                            .titleLarge\n                            ?.copyWith(fontWeight: FontWeight.w900),\n                      ),\n                    ],\n                  ),\n                  if ((transaction['payment_method']?.toString() ?? '')\n                      .isNotEmpty) ...[\n                    const SizedBox(height: 10),\n                    Text(\n                      'Pagamento: ${_paymentMethod(transaction['payment_method']?.toString())}',\n                    ),\n                  ],\n                  if ((transaction['notes']?.toString() ?? '').isNotEmpty) ...[\n                    const SizedBox(height: 8),\n                    Text(transaction['notes'].toString()),\n                  ],\n                ],\n              ),\n            ),\n          ),\n          const SizedBox(height: 16),\n          if (transactionId.isEmpty)\n            const Card(\n              child: ListTile(\n                leading: Icon(Icons.error_outline),\n                title: Text('Movimento sem identificador.'),\n              ),\n            )\n          else\n            FinancialDocumentGallery(\n              repository: repository,\n              transactionId: transactionId,\n              canManage: repository.canManage,\n              onChanged: onChanged,\n            ),\n          const SizedBox(height: 16),\n          Card(\n            child: ListTile(\n              leading: const Icon(Icons.verified_user_outlined),\n              title: const Text('Arquivo financeiro auditado'),\n              subtitle: const Text(\n                'Cada ficheiro fica associado individualmente ao movimento. '\n                'Talões e comprovativos herdados de pedidos financeiros são '\n                'mantidos como evidência e não são duplicados no Storage.',\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  static String _money(Object? value) {\n    final amount = value is num\n        ? value.toDouble()\n        : double.tryParse(value?.toString() ?? '') ?? 0;\n    return '${amount.toStringAsFixed(2).replaceAll('.', ',')} €';\n  }\n\n  static String _paymentMethod(String? value) {\n    if (value == null || value.isEmpty) return '—';\n    return switch (value) {\n      'cash' => 'Numerário',\n      'mbway' => 'MB Way',\n      'bank_transfer' => 'Transferência bancária',\n      'other' => 'Outro',\n      _ => value,\n    };\n  }\n}\n", 'apps/mobile/test/financial_documents_gallery_test.dart': "import 'package:bob_manager_mobile/repositories/financial_documents_repository.dart';\nimport 'package:flutter_test/flutter_test.dart';\n\nvoid main() {\n  test('categorias financeiras têm rótulos estáveis', () {\n    expect(\n      FinancialDocumentsRepository.documentTypeLabel('receipt'),\n      'Talão / recibo',\n    );\n    expect(\n      FinancialDocumentsRepository.documentTypeLabel('payment_proof'),\n      'Comprovativo de pagamento',\n    );\n    expect(\n      FinancialDocumentsRepository.documentTypeLabel('invoice_other'),\n      'Fatura / PDF / outro',\n    );\n  });\n\n  test('reconhece imagens pelo MIME type', () {\n    expect(\n      FinancialDocumentsRepository.isImage({\n        'mime_type': 'image/jpeg',\n        'original_file_name': 'talao.jpg',\n      }),\n      isTrue,\n    );\n  });\n\n  test('reconhece PDF pelo nome quando MIME type não existe', () {\n    expect(\n      FinancialDocumentsRepository.isPdf({\n        'mime_type': null,\n        'original_file_name': 'fatura.PDF',\n      }),\n      isTrue,\n    );\n  });\n\n  test('documentos herdados de pedidos não são elimináveis', () {\n    expect(\n      FinancialDocumentsRepository.isDeletable({\n        'origin': 'request',\n        'source_attachment_id': 'attachment-id',\n      }),\n      isFalse,\n    );\n  });\n\n  test('documentos carregados diretamente são elimináveis', () {\n    expect(\n      FinancialDocumentsRepository.isDeletable({\n        'origin': 'direct',\n        'source_attachment_id': null,\n      }),\n      isTrue,\n    );\n  });\n}\n", 'supabase/migrations/20260811184814_rc1_financial_documents_gallery.sql': "-- Commit 9: documentos/comprovativos financeiros + galeria por movimento.\n\ncreate table if not exists public.financial_transaction_documents (\n  id uuid primary key default gen_random_uuid(),\n  club_id uuid not null references public.clubs(id) on delete cascade,\n  transaction_id uuid not null references public.treasury_transactions(id) on delete cascade,\n  source_attachment_id uuid references public.financial_request_attachments(id) on delete set null,\n  document_type text not null check (document_type in ('receipt','payment_proof','invoice_other')),\n  origin text not null default 'direct' check (origin in ('direct','request','bar_ocr','import')),\n  storage_path text not null,\n  original_file_name text not null,\n  mime_type text,\n  file_size bigint not null default 0 check (file_size >= 0 and file_size <= 20971520),\n  is_primary boolean not null default false,\n  created_at timestamptz not null default now(),\n  created_by uuid references public.profiles(id) on delete set null,\n  updated_at timestamptz not null default now(),\n  updated_by uuid references public.profiles(id) on delete set null,\n  unique(transaction_id,storage_path)\n);\n\ncreate index if not exists financial_transaction_documents_tx_idx\n  on public.financial_transaction_documents(transaction_id,created_at,id);\ncreate unique index if not exists financial_transaction_documents_source_uidx\n  on public.financial_transaction_documents(transaction_id,source_attachment_id)\n  where source_attachment_id is not null;\ncreate unique index if not exists financial_transaction_documents_primary_uidx\n  on public.financial_transaction_documents(transaction_id)\n  where is_primary=true;\n\ndrop trigger if exists financial_transaction_documents_audit_stamp on public.financial_transaction_documents;\ncreate trigger financial_transaction_documents_audit_stamp\nbefore insert or update on public.financial_transaction_documents\nfor each row execute function public.audit_stamp_row_v1();\n\ndrop trigger if exists financial_transaction_documents_audit_capture on public.financial_transaction_documents;\ncreate trigger financial_transaction_documents_audit_capture\nafter insert or update or delete on public.financial_transaction_documents\nfor each row execute function public.audit_capture_row_v1();\n\ncreate or replace function public.refresh_financial_transaction_primary_v1(p_transaction uuid)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare v_id uuid; v_path text;\nbegin\n  select d.id,d.storage_path into v_id,v_path\n  from public.financial_transaction_documents d\n  where d.transaction_id=p_transaction and d.is_primary=true\n  order by d.created_at,d.id\n  limit 1;\n\n  if v_id is null then\n    select d.id,d.storage_path into v_id,v_path\n    from public.financial_transaction_documents d\n    where d.transaction_id=p_transaction\n    order by d.created_at,d.id\n    limit 1;\n    if v_id is not null then\n      update public.financial_transaction_documents\n      set is_primary=true\n      where id=v_id;\n    end if;\n  end if;\n\n  update public.treasury_transactions t\n  set document_path=v_path\n  where t.id=p_transaction\n    and t.document_path is distinct from v_path;\nend;\n$$;\n\ncreate or replace function public.add_financial_transaction_document_v1(\n  target_club uuid,\n  p_transaction uuid,\n  p_document_type text,\n  p_storage_path text,\n  p_original_file_name text,\n  p_mime_type text,\n  p_file_size bigint\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare v_id uuid;\nbegin\n  if auth.uid() is null or not (\n    public.has_club_permission(target_club,'createTreasuryMovement')\n    or public.has_club_permission(target_club,'approveExpenseRequests')\n  ) then raise exception 'Sem autorização para gerir documentos financeiros.'; end if;\n\n  if not exists(\n    select 1 from public.treasury_transactions t\n    where t.id=p_transaction and t.club_id=target_club\n  ) then raise exception 'Movimento financeiro não encontrado.'; end if;\n\n  if p_document_type not in ('receipt','payment_proof','invoice_other') then\n    raise exception 'Categoria de documento inválida.';\n  end if;\n  if p_file_size is null or p_file_size<=0 or p_file_size>20971520 then\n    raise exception 'O ficheiro deve ter entre 1 byte e 20 MB.';\n  end if;\n  if p_storage_path not like target_club::text||'/transactions/'||p_transaction::text||'/%' then\n    raise exception 'Caminho de armazenamento inválido.';\n  end if;\n\n  insert into public.financial_transaction_documents(\n    club_id,transaction_id,document_type,origin,storage_path,\n    original_file_name,mime_type,file_size,is_primary\n  ) values (\n    target_club,p_transaction,p_document_type,'direct',p_storage_path,\n    coalesce(nullif(btrim(p_original_file_name),''),'ficheiro'),\n    nullif(btrim(coalesce(p_mime_type,'')),''),p_file_size,false\n  ) returning id into v_id;\n\n  perform public.refresh_financial_transaction_primary_v1(p_transaction);\n  return v_id;\nend;\n$$;\n\ncreate or replace function public.set_primary_financial_transaction_document_v1(\n  target_club uuid,\n  p_transaction uuid,\n  p_document uuid\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\nbegin\n  if auth.uid() is null or not (\n    public.has_club_permission(target_club,'createTreasuryMovement')\n    or public.has_club_permission(target_club,'approveExpenseRequests')\n  ) then raise exception 'Sem autorização para gerir documentos financeiros.'; end if;\n\n  if not exists(\n    select 1 from public.financial_transaction_documents d\n    where d.id=p_document and d.transaction_id=p_transaction and d.club_id=target_club\n  ) then raise exception 'Documento não encontrado.'; end if;\n\n  update public.financial_transaction_documents\n  set is_primary=false\n  where club_id=target_club and transaction_id=p_transaction and is_primary=true;\n\n  update public.financial_transaction_documents\n  set is_primary=true\n  where id=p_document and club_id=target_club and transaction_id=p_transaction;\n\n  perform public.refresh_financial_transaction_primary_v1(p_transaction);\nend;\n$$;\n\ncreate or replace function public.delete_financial_transaction_document_v1(\n  target_club uuid,\n  p_transaction uuid,\n  p_document uuid\n)\nreturns text\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare d public.financial_transaction_documents%rowtype; v_path text;\nbegin\n  if auth.uid() is null or not (\n    public.has_club_permission(target_club,'createTreasuryMovement')\n    or public.has_club_permission(target_club,'approveExpenseRequests')\n  ) then raise exception 'Sem autorização para gerir documentos financeiros.'; end if;\n\n  select * into d\n  from public.financial_transaction_documents\n  where id=p_document and transaction_id=p_transaction and club_id=target_club\n  for update;\n  if not found then raise exception 'Documento não encontrado.'; end if;\n  if d.source_attachment_id is not null then\n    raise exception 'Este documento pertence ao processo financeiro original e não pode ser eliminado aqui.';\n  end if;\n\n  v_path:=d.storage_path;\n  delete from public.financial_transaction_documents where id=d.id;\n  perform public.refresh_financial_transaction_primary_v1(p_transaction);\n  return v_path;\nend;\n$$;\n\ncreate or replace function public.sync_financial_request_documents_v1()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\nbegin\n  if new.treasury_transaction_id is null then return new; end if;\n  if tg_op='UPDATE' and new.treasury_transaction_id is not distinct from old.treasury_transaction_id then\n    return new;\n  end if;\n\n  insert into public.financial_transaction_documents(\n    club_id,transaction_id,source_attachment_id,document_type,origin,\n    storage_path,original_file_name,mime_type,file_size,is_primary,\n    created_at,created_by,updated_at,updated_by\n  )\n  select\n    a.club_id,new.treasury_transaction_id,a.id,\n    case\n      when a.kind='receipt' then 'receipt'\n      when a.kind in ('member_payment_proof','club_payment_proof') then 'payment_proof'\n      else 'invoice_other'\n    end,\n    'request',a.storage_path,a.original_file_name,a.mime_type,a.file_size,false,\n    a.created_at,a.created_by,a.updated_at,a.updated_by\n  from public.financial_request_attachments a\n  where a.request_id=new.id\n  on conflict do nothing;\n\n  perform public.refresh_financial_transaction_primary_v1(new.treasury_transaction_id);\n  return new;\nend;\n$$;\n\ndrop trigger if exists financial_request_transaction_documents_sync on public.financial_requests;\ncreate trigger financial_request_transaction_documents_sync\nafter update of treasury_transaction_id on public.financial_requests\nfor each row execute function public.sync_financial_request_documents_v1();\n\n-- Backfill dos pedidos/cobranças já liquidados: apenas liga metadados, sem duplicar ficheiros no Storage.\ninsert into public.financial_transaction_documents(\n  club_id,transaction_id,source_attachment_id,document_type,origin,\n  storage_path,original_file_name,mime_type,file_size,is_primary,\n  created_at,created_by,updated_at,updated_by\n)\nselect\n  a.club_id,r.treasury_transaction_id,a.id,\n  case\n    when a.kind='receipt' then 'receipt'\n    when a.kind in ('member_payment_proof','club_payment_proof') then 'payment_proof'\n    else 'invoice_other'\n  end,\n  'request',a.storage_path,a.original_file_name,a.mime_type,a.file_size,false,\n  a.created_at,a.created_by,a.updated_at,a.updated_by\nfrom public.financial_requests r\njoin public.financial_request_attachments a on a.request_id=r.id\nwhere r.treasury_transaction_id is not null\non conflict do nothing;\n\ndo $$\ndeclare r record;\nbegin\n  for r in select distinct transaction_id from public.financial_transaction_documents loop\n    perform public.refresh_financial_transaction_primary_v1(r.transaction_id);\n  end loop;\nend;\n$$;\n\nalter table public.financial_transaction_documents enable row level security;\n\ndrop policy if exists financial_transaction_documents_read on public.financial_transaction_documents;\ncreate policy financial_transaction_documents_read on public.financial_transaction_documents\nfor select to authenticated\nusing (\n  public.has_club_permission(club_id,'viewTreasury')\n  or public.has_club_permission(club_id,'approveExpenseRequests')\n);\n\ngrant select on table public.financial_transaction_documents to authenticated;\nrevoke insert,update,delete on table public.financial_transaction_documents from anon,authenticated;\n\n-- O mesmo bucket privado serve pedidos e movimentos financeiros.\ncreate or replace function public.financial_storage_access_v2(p_name text,p_manage boolean default false)\nreturns boolean\nlanguage plpgsql\nstable\nsecurity definer\nset search_path=public,storage\nas $$\ndeclare folders text[]; v_request uuid; v_transaction uuid; v_club uuid;\nbegin\n  if auth.uid() is null then return false; end if;\n  folders:=storage.foldername(p_name);\n  if coalesce(array_length(folders,1),0)<2 then return false; end if;\n\n  if folders[2]='transactions' then\n    if coalesce(array_length(folders,1),0)<3 then return false; end if;\n    begin\n      v_transaction:=folders[3]::uuid;\n    exception when invalid_text_representation then\n      return false;\n    end;\n\n    select t.club_id into v_club\n    from public.treasury_transactions t where t.id=v_transaction;\n    if not found or folders[1] is distinct from v_club::text then return false; end if;\n\n    if p_manage then\n      return public.has_club_permission(v_club,'createTreasuryMovement')\n          or public.has_club_permission(v_club,'approveExpenseRequests');\n    end if;\n    return public.has_club_permission(v_club,'viewTreasury')\n        or public.has_club_permission(v_club,'approveExpenseRequests');\n  end if;\n\n  begin\n    v_request:=folders[2]::uuid;\n  exception when invalid_text_representation then\n    return false;\n  end;\n  select r.club_id into v_club\n  from public.financial_requests r where r.id=v_request;\n  if not found or folders[1] is distinct from v_club::text then return false; end if;\n  return public.financial_request_access_v1(v_request);\nend;\n$$;\n\ndrop policy if exists financial_documents_select on storage.objects;\ncreate policy financial_documents_select on storage.objects\nfor select to authenticated\nusing (\n  bucket_id='financial-documents'\n  and public.financial_storage_access_v2(name,false)\n);\n\ndrop policy if exists financial_documents_insert on storage.objects;\ncreate policy financial_documents_insert on storage.objects\nfor insert to authenticated\nwith check (\n  bucket_id='financial-documents'\n  and public.financial_storage_access_v2(name,true)\n);\n\ndrop policy if exists financial_documents_delete on storage.objects;\ncreate policy financial_documents_delete on storage.objects\nfor delete to authenticated\nusing (\n  bucket_id='financial-documents'\n  and public.financial_storage_access_v2(name,true)\n);\n\nrevoke all on function public.refresh_financial_transaction_primary_v1(uuid) from public,anon,authenticated;\nrevoke all on function public.sync_financial_request_documents_v1() from public,anon,authenticated;\n\nrevoke all on function public.financial_storage_access_v2(text,boolean) from public,anon;\ngrant execute on function public.financial_storage_access_v2(text,boolean) to authenticated;\n\nrevoke all on function public.add_financial_transaction_document_v1(uuid,uuid,text,text,text,text,bigint) from public,anon;\ngrant execute on function public.add_financial_transaction_document_v1(uuid,uuid,text,text,text,text,bigint) to authenticated;\nrevoke all on function public.set_primary_financial_transaction_document_v1(uuid,uuid,uuid) from public,anon;\ngrant execute on function public.set_primary_financial_transaction_document_v1(uuid,uuid,uuid) to authenticated;\nrevoke all on function public.delete_financial_transaction_document_v1(uuid,uuid,uuid) from public,anon;\ngrant execute on function public.delete_financial_transaction_document_v1(uuid,uuid,uuid) to authenticated;\n", 'docs/COMMIT9_FINANCIAL_DOCUMENTS_GALLERY.md': '# Commit 9 — Documentos/comprovativos financeiros + galeria\n\n## Objetivo\nAssociar múltiplos documentos a cada movimento de Tesouraria sem substituir o histórico por um único `document_path`.\n\n## Categorias\n- Talão / recibo (`receipt`)\n- Comprovativo de pagamento (`payment_proof`)\n- Fatura / PDF / outro (`invoice_other`)\n\n## Regras principais\n- Os ficheiros continuam no bucket privado `financial-documents`.\n- Cada movimento pode ter vários documentos e um documento principal.\n- Documentos provenientes da Central de Pedidos & Pagamentos são ligados ao movimento quando este é liquidado, sem duplicar o objeto no Storage.\n- Documentos herdados de pedidos ficam protegidos contra eliminação na galeria do movimento.\n- Documentos carregados diretamente na Tesouraria podem ser eliminados por utilizadores com permissão financeira adequada.\n- O campo legado `treasury_transactions.document_path` passa a refletir o documento principal para compatibilidade.\n- Auditoria global é aplicada à nova tabela.\n- A origem `bar_ocr` fica reservada para o Commit 11, permitindo preservar cada original individualmente.\n\n## Interface\nAo tocar num movimento em Tesouraria abre-se a página `Documentos do movimento`, com padrão visual inspirado na Galeria 2.2:\n- documento principal em destaque;\n- miniaturas/documentos secundários;\n- abertura de imagem com zoom;\n- PDF aberto externamente através de URL assinada;\n- carregamento múltiplo;\n- escolha da categoria;\n- definição do documento principal.\n'}

